def rotate(data, w, h):
    tokens = data.split()
    axis = 0
    for i, token in enumerate(tokens):
        if token in 'MLCZ':
            axis = 0
        else:
            tokens[i] = str(round((w if axis % 2 == 0 else h) - float(token), 3))
            axis += 1
    return ' '.join(tokens)

OUTLINES['0'] = OUTLINES['O']
OUTLINES['9'] = rotate(OUTLINES['6'], 685, 1000)
for ch, stems, w in [('Ⅰ', [230], 620), ('Ⅱ', [200, 480], 800), ('Ⅲ', [200, 500, 800], 1160)]:
    # A single perimeter plus rectangular counters avoids overlapping fills.
    path = f'M 0 0 L {w} 0 L {w} 120 L {stems[-1]+120} 120 L {stems[-1]+120} 880 L {w} 880 L {w} 1000 L 0 1000 L 0 880 L {stems[0]} 880 L {stems[0]} 120 L 0 120 Z'
    for a, b in zip(stems, stems[1:]):
        path += f' M {a+120} 120 L {b} 120 L {b} 880 L {a+120} 880 Z'
    OUTLINES[ch] = path

sign_widths = dict(zip('ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789', [850,685,685,685,620,620,685,685,160,635,700,620,785,685,715,685,715,685,685,620,685,760,890,685,855,685,715,245,685,685,745,685,685,685,685,685]))
# Measured figure proportions, rounded to remove raster-edge fluctuations.
ground_widths = dict(zip('ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789', [340,270,255,285,255,250,265,270,63,260,260,250,320,270,275,275,265,280,270,255,275,305,340,255,325,290,275,100,265,270,310,275,275,275,265,270]))

root = ET.Element('glyphs', version='2', method='low-node geometric reference redraw')
for family, widths in [('sign', sign_widths), ('ground', ground_widths)]:
    extras = {'↑':700, '-':350, '.':160, '/':650, 'Ⅰ':620, 'Ⅱ':800, 'Ⅲ':1160} if family == 'sign' else {'↑':300, '-':300, '.':64, '/':260, 'm':298}
    for ch, width in dict(widths, **extras).items():
        data = OUTLINES[ch]
        if family == 'ground' and ch == '↑':
            data = 'M 150 0 L 300 500 L 180 400 L 180 1000 L 120 1000 L 120 400 L 0 500 Z'
        height = 120 if ch == '-' else 160 if ch == '.' else 700 if ch == 'm' else 1000
        ET.SubElement(root, 'glyph', family=family, char=ch, width=str(width), height=str(height),
                      page='86-90' if family == 'ground' else '262-264', d=data)
ET.indent(root)
ET.ElementTree(root).write(ROOT/'assets/glyphs.xml', encoding='utf-8', xml_declaration=True)
print(f'Wrote {len(root)} clean vector glyphs')
